from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];d=json.loads((r/'tools/compact_evidence_source.json').read_text());out=[]
def setfield(pm,key,new,finding,source):
 old=d['studies'][pm][key]
 out.append({'file':'tools/compact_evidence_source.json','json_path':['studies',pm,key],'old':old,'new':new,'finding_id':finding,'source_locator':source})
setfield('34554208','result','Final ITT OS 10.3 vs 7.5 mo (HR 0.79, 95% CI 0.56–1.12; P=.09); corrected crossover-adjusted HR 0.49 (bootstrap 95% CI 0.25–1.24); primary PFS HR 0.37','HB040','A hepatobiliary/Source_Reviews/42879142.md; October2026 correction PMID42879142, current Fig2')
